     "<script async src=\"https://www.googletagmanager.com/gtag/js?id=G-PSW1MY7HB4\"></script>",
     "<script>",
     "window.dataLayer = window.dataLayer || [];",
     "function gtag(){dataLayer.push(arguments);}",
